 speak:(line,language,notice)=>{const accepted=soulChat.isOpen()?soulChat.announceWeather(line,language):handsFree?.announce(line,language);if(accepted&&screen==='ride'&&ride){(ride.weatherEvents??=[]).push({kind:notice.kind,at:Date.now()});if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent=line;$('quoteTitle').textContent='WEATHER · Open-Meteo';}}return !!accepted;},
