function shell(copy,body,step=0){return `<section class="experience"><div class="experience-copy"><button class="back" data-nav="home">← 소울 만나기로</button><span class="eyebrow">A LITTLE SOUL. A DIFFERENT RIDE.</span><h1>${copy.title}</h1><p>${copy.text}</p><div class="progress">${['01 만나기','02 함께 달리기','03 기억 남기기'].map((t,i)=>`<span class="${i===step?'active':''}">${t}</span>`).join('')}</div></div><div class="phone">${body}</div></section>`;}
function phoneHead(title,sub,action=''){return `<div class="phone-head"><div><b>${title}</b><small>${sub}</small></div>${action||'<span class="pill"><span class="dot"></span> SOUL CONNECTED</span>'}</div>`;}
