function welcome(id){theme(id);const s=SOULS[id];surface('welcome',`<section class="meeting-page"><div class="meeting-top"><button class="back" data-nav="home">← 소울 만나기로</button><span class="eyebrow">BIKE ${s.number} / A LITTLE ENCOUNTER</span></div><div class="meeting-stage"><div class="meeting-portrait entrance-${id}"><span class="meeting-name" aria-hidden="true">${s.en}</span><span class="meeting-orbit" aria-hidden="true"></span><span class="meeting-spark spark-one" aria-hidden="true">✧</span><span class="meeting-spark spark-two" aria-hidden="true">✦</span><div class="welcome-puppet">${soulPuppet(id)}</div><span class="meeting-trait">${s.type}</span></div><div class="meeting-copy"><span class="eyebrow">이 자전거의 친구</span><h1>안녕, 나는 ${s.name}야.</h1><blockquote>“${s.invite}”</blockquote><p class="meeting-description">${s.desc}</p><div class="meeting-actions"><button class="primary accent" data-action="live-companion">함께 출발하기 <span aria-hidden="true">↗</span></button></div><div class="voice-status" aria-live="polite"></div>${riderReviews.markup('welcome')}</div></div><p class="meeting-footer">잠깐 멈춘 뒤 시작해요. 달리는 동안에는 목소리로 함께해요.</p></section>`);updateURL('bike='+id);characterMotion.enter(id);}
function cameraMarkup(mode){const scanning=mode==='scan';return `<div class="camera-view ${scanning?'scanning':''}" id="cameraView"><video id="cameraVideo" autoplay playsinline muted aria-label="실시간 후면 카메라"></video><div class="camera-placeholder"><div class="camera-empty"><span class="camera-icon">${scanning?'⌗':'◎'}</span><b>${scanning?'자전거의 QR을 비춰주세요':'당신의 세상으로 초대해요'}</b><p>${scanning?'카메라를 켜고 세 소울의 QR 코드 중 하나를 화면 안에 담아주세요.':'카메라를 켜면 화면 위로 소울이 나타나요.'}</p></div></div><span class="camera-label" id="cameraLabel">CAMERA OFF</span>${scanning?'<div class="scan-target" aria-hidden="true"></div>':`<div class="soul-portal" aria-hidden="true"><i></i><i></i><i></i><span>✦</span><span>✧</span><span>·</span></div><div class="soul-overlay ${selected}" id="soulOverlay" data-ride-direction="${mode==='ride'?'forward':'portrait'}">${soulPuppet(selected)}</div>`}<span class="ar-hint">${scanning?'VELO SOUL 전용 QR 인식':'화면 위의 작은 동반자 · 드래그로 돌려보기'}</span></div><aside id="cameraRecovery" class="camera-recovery" data-no-translate hidden></aside>`;}
function encounter(preview=false,withVoice=false){encounterPhotos=[];latestPhoto=null;surface('camera',fullCameraMarkup(false));document.body.classList.add('camera-open');updateURL(`bike=${selected}&view=camera`);bindCamera();updateGPSUI();if(preview)wake();else{if(withVoice){companionPending=true;startHandsFree();if(watch===null)gps();}camera.start();}}
