function bindCamera(scan=false){camera=new SoulCameraController({video:$('cameraVideo'),onState:(state,message,code)=>{paintCameraRecovery({state,code,language:getLanguage(),selected,scanning:scan});camState=state;rideView.cameraStatus();const view=$('cameraView');if(!view)return;if(state!=='live')visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=state!=='live';view.classList.toggle('live',state==='live');$('cameraLabel').textContent=state==='live'?'● LIVE CAMERA':view.classList.contains('awakened')?'CAMERA-FREE PREVIEW':'CAMERA OFF';$('cameraStatus').textContent=message;const b=$('cameraStart');if(b){b.disabled=state==='requesting';b.textContent=state==='requesting'?'권한 요청 중…':state==='live'?'카메라 끄기':'카메라 켜기';}if($('wakeButton'))$('wakeButton').textContent='✦';if($('capturePhoto'))$('capturePhoto').disabled=state!=='live';if(scan&&state==='live')scanFrame();else if(state==='live') {wakeCameraEntrance();if(screen==='camera')wake();if(companionPending){companionPending=false;toggleVision();}}}});}
