function wake(){characterMotion.enter(selected);if(camState==='requesting'){camera?.stop();camState='off';$('cameraStart').disabled=false;$('cameraStart').textContent='카메라 켜기';}const view=$('cameraView');view.classList.remove('awakened');void view.offsetWidth;view.classList.add('awakened');$('cameraLabel').textContent=camState==='live'?'● LIVE CAMERA':'CAMERA-FREE PREVIEW';$('wakeButton').textContent='✦';if($('rideStart'))$('rideStart').hidden=false;voiceOn=true;if(!handsFree?.active)speak(SOULS[selected].hello,'hello');$('cameraStatus').textContent=camState==='live'?'카메라 화면 위에 소울이 나타났어요.':'카메라 없는 애니메이션 미리보기예요.';}
let qrDecoderLoading=false;
function loadQRDecoder(){if(window.jsQR||qrDecoderLoading)return;qrDecoderLoading=true;const script=document.createElement('script');script.src=`/vendor/jsQR.js?v=${BUILD}`;script.onload=()=>{qrDecoderLoading=false;};script.onerror=()=>{qrDecoderLoading=false;if(['home','scan'].includes(screen))toast('QR 인식을 불러오지 못했어요. 스캔 버튼을 눌러 다시 시도해주세요.');};document.head.append(script);}
const scanCanvas=document.createElement('canvas');
function scanFrame(){if(!['home','scan'].includes(screen)||camState!=='live'||!camera)return;const v=$('cameraVideo');if(v?.readyState>=2&&v.videoWidth){const w=Math.min(v.videoWidth,640),h=Math.round(v.videoHeight*w/v.videoWidth);scanCanvas.width=w;scanCanvas.height=h;const ctx=scanCanvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(v,0,0,w,h);const pixels=ctx.getImageData(0,0,w,h);const code=window.jsQR?.(pixels.data,w,h,{inversionAttempts:'dontInvert'});if(code){const id=parseSoulQR(code.data,location.origin);if(id){stopCamera();welcome(id);toast(`${SOULS[id].name}의 QR을 찾았어요!`);return;}$('cameraStatus').textContent='VELO SOUL의 전용 QR 코드를 비춰주세요.';}}scanTimer=setTimeout(scanFrame,180);}
function startRide(){placeFence=new PlaceFence();const s=SOULS[selected];ride={id:crypto.randomUUID(),soul:selected,started:Date.now(),createdAt:Date.now(),route:[],photos:encounterPhotos.splice(0),placeEvents:[],events:[],conversation:[],note:'',seconds:0,gpsStatus:'위치 기록을 켜면 실제 이동 경로가 남아요.',speed:null};if(latestPhoto?.photos===encounterPhotos)latestPhoto.photos=ride.photos;voiceOn=true;renderRide();}
function routeSVG(points){return journeyMap(points); }
function renderRide(){const s=SOULS[selected];surface('ride',`<section class="ride-layout"><div class="ride-primary"><div class="ride-header"><div><span class="eyebrow">02 / TOGETHER ON THE ROAD</span><h1>${s.name}와 함께 달리는 중</h1></div><span class="pill" style="color:var(--accent)">${s.emoji} ${s.tag}</span></div><div class="companion">${soulPuppet(selected)}<span class="orb-text">I'M RIGHT HERE WITH YOU</span></div><div class="quote-box"><div class="quote-top"><span id="quoteTitle">${s.name}의 목소리</span>${wave}</div><p id="rideQuote">“좋아, 출발하자. 나는 네 곁에 있을게.”</p><div class="quote-actions"><span class="voice-status" aria-live="polite"></span><button data-action="replay">다시 듣기 ♪</button></div></div><div class="ride-toolbar">${audioDeviceButton(getLanguage())}${rideVoiceControlsMarkup(getLanguage(),!!handsFree?.active,handsFree?.state||'off')}<button class="primary accent" data-action="live-companion">GPS · 카메라 · 음성 함께 시작</button><button class="secondary" data-action="ride-camera">◎ 카메라 · 순간 담기</button><button class="secondary chat-entry" data-action="chat">소울과 대화하기 ↗</button><button class="secondary" id="quietButton" data-action="quiet">♪ 목소리 쉬기</button></div></div><aside class="ride-side"><div class="panel"><h2>우리의 지금</h2><div class="metric-row"><div><b id="rideTime">00:00</b><span>함께한 시간</span></div><div><b id="rideDistance">—</b><span>거리 · km</span></div><div><b id="rideSpeed">—</b><span>GPS 속도 · km/h</span></div></div><button class="secondary" id="gpsButton" data-action="gps" data-gps-toggle data-no-translate>위치 기록 켜기</button><p class="sensor-status" id="gpsStatus" data-gps-status data-no-translate>${ride.gpsStatus}</p><p id="locationDetail" class="small" data-no-translate></p>${weatherMarkup(getLanguage())}<div id="rideMap">${mapMarkup(getLanguage(),true)}</div><div class="place-panel"><b>근처 장소에서 소울이 말해요</b><p class="small">등록한 서울 장소 3곳 · GPS 허용 후 자동 감지. 대화에는 장소와 날씨 요약을 보내요. 날씨 조회에는 약 2km 격자 위치를 사용해요.</p><p id="placeStatus" class="small" role="status">GPS를 켜면 근처 장소를 기다려요.</p></div></div><div class="panel"><h2>소울과 고른 순간 <span id="photoCount" class="small">사진 ${ride.photos.length}장</span></h2><div id="photoStrip" class="${ride.photos.length?'memory-preview':'empty-photos'}">${ride.photos.length?ride.photos.map((src,i)=>photoLink(src,ride.soul,ride.createdAt,i)).join(''):'잠깐 멈춰서, 함께 기억할 장면을 담아요.'}</div><button class="primary" data-action="finish">여정 마치고 기록 남기기 →</button><p class="small" style="margin-bottom:0">주행 중에는 화면 대신 목소리에 귀 기울여요.</p></div></aside></section>`);currentLine={line:'좋아, 출발하자. 나는 네 곁에 있을게.',key:'start'};updateURL(`bike=${selected}&view=ride`);timer=setInterval(updateRideMetrics,1000);updateGPSUI();}
function updateRideMetrics(){if(!ride||screen!=='ride')return;$('rideTime').textContent=duration((Date.now()-ride.started)/1000);$('rideDistance').textContent=ride.route.length>1?(routeDistance(ride.route)/1000).toFixed(2):'—';$('rideSpeed').textContent=Number.isFinite(ride.speed)?ride.speed.toFixed(1):'—';}
function gps(){
 if(watch!==null){stopGPS();if(ride)ride.speed=null;gpsConnection='paused';gpsStatus='위치 기록을 잠시 멈췄어요.';updateGPSUI();return;}
 if(!deviceGPS()||!window.isSecureContext){gpsConnection='unsupported';gpsStatus='이 환경에서는 위치를 사용할 수 없어요. HTTPS 주소를 휴대폰에서 열어주세요.';updateGPSUI();return;}
 gpsConnection='waiting';gpsStatus='위치 권한과 GPS 신호를 기다리고 있어요.';weather.start();const epoch=++gpsEpoch;
 try{const id=deviceGPS().watchPosition(pos=>{
  if(epoch!==gpsEpoch)return;
  const p=validGPSPoint(pos),c=pos?.coords;if(!p){gpsConnection='weak';gpsPoint=null;gpsSpeed=null;characterMotion.pause();placeFence?.pause();if(ride)ride.speed=null;updateGPSUI();return;}gpsPoint=p;if(screen==='ride'&&ride)ride.latestPoint=p;
  if(c.accuracy>60){gpsConnection='weak';placeFence?.pause();gpsStatus='GPS 오차가 커서 기다리는 중이에요 (±'+Math.round(c.accuracy)+'m).';gpsSpeed=null;characterMotion.pause();if(ride)ride.speed=null;updateGPSUI();return;}
  gpsConnection='connected';gpsSpeed=Number.isFinite(c.speed)&&c.speed>=0&&c.speed<25?c.speed*3.6:null;gpsStatus='위치와 주변 날씨를 함께 확인하고 있어요.';characterMotion.sample(gpsSpeed,{accuracy:p.accuracy,time:p.time});weather.position(p);
  if(screen==='ride'&&ride){ride.speed=gpsSpeed;if(ride.route.length<1800&&appendPoint(ride.route,p)&&$('rideMap'))koreanMap.update(ride.route);
   if(!weather.openingPending()&&!soulChat.isOpen()&&!handsFree?.isBusy()&&!placeRequest&&!document.body.classList.contains('voice-playing')){const place=placeFence?.update(p);if(place)triggerPlace(place);}
   if(!soulChat.isOpen()&&!handsFree?.isBusy()&&!placeRequest&&!document.body.classList.contains('voice-playing')&&selected==='mori'&&ride.speed>22&&!ride.events.includes('actual-speed')){ride.events.push('actual-speed');const line=voiceLanguage==='ko'?SCENARIOS.mori[0].line:'We seem to be riding quite quickly. If you would like, we can ease our pace a little.';if($('rideQuote'))$('rideQuote').textContent=line;sayLive(line,voiceLanguage);}
  }updateGPSUI();
 },err=>{if(epoch!==gpsEpoch)return;gpsStatus=err.code===1?'위치 권한이 꺼져 있어요. 브라우저 사이트 설정에서 허용한 뒤 다시 시도해주세요.':'위치 신호를 찾지 못했어요. 실외에서 다시 시도해주세요.';stopGPS();gpsConnection=err.code===1?'denied':'error';if(ride)ride.speed=null;updateGPSUI();},{enableHighAccuracy:true,maximumAge:2000,timeout:15000});if(epoch===gpsEpoch)watch=id;else deviceGPS().clearWatch(id);}catch{stopGPS();gpsConnection='error';}updateGPSUI();
}
function updateGPSUI(){
 gpsStatus=paintGPS(document,{language:getLanguage(),state:gpsConnection,active:watch!==null,point:gpsPoint});
 rideView.update();if(['home','welcome'].includes(screen))koreanMap.update(gpsPoint&&gpsConnection==='connected'?[gpsPoint]:[]);
 if(ride)ride.gpsStatus=gpsStatus;
 if($('locationDetail'))$('locationDetail').textContent=gpsPoint?gpsPoint.lat.toFixed(5)+', '+gpsPoint.lon.toFixed(5)+' · ±'+Math.round(gpsPoint.accuracy)+' m':'';
 if($('cameraGPS'))$('cameraGPS').textContent=gpsConnection==='connected'?'GPS ● ±'+Math.round(gpsPoint.accuracy)+' m':gpsConnection==='waiting'?'GPS …':'GPS ○';
 updateRideMetrics();paintWeatherUI();
}

function rideCamera(withVoice=false){if($('rideCameraModal'))return;if(!handsFree?.active)stopVoice();stopPlaceTalk();const overlay=document.createElement('div');overlay.id='rideCameraModal';overlay.className='ride-camera-modal camera-fullscreen';overlay.dataset.sceneMode='camera';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label',translate('함께 기억할 순간'));overlay.innerHTML=fullCameraInner(true);document.body.append(overlay);document.body.classList.add('camera-open');mountCharacters();paintCharacterMotion(document,characterMotion.snapshot(),getLanguage());bindCamera();updateGPSUI();if(withVoice){companionPending=true;startHandsFree();}camera.start();}
function closeRideCamera(){rideView.destroy();companionPending=false;stopCamera();$('rideCameraModal')?.remove();document.body.classList.remove('camera-open');document.querySelector('[data-action="ride-camera"]')?.focus();}
function photoLink(src,soul,time,index){return '<a href="'+esc(src)+'" download="'+photoFilename(soul,time,index+1)+'" title="사진 다시 저장"><img src="'+esc(src)+'" alt="함께 담은 순간 '+(index+1)+'" loading="lazy"></a>';}
function photoSavedMessage(){return isNative()?({en:'Saved in this app. Tap the photo to export or share.',ko:'앱에 저장했어요. 사진을 누르면 내보내거나 공유할 수 있어요.',zh:'已保存在 App 内，点击照片可导出或分享。'})[getLanguage()]:'사진 다운로드를 요청했어요. 휴대폰의 다운로드 또는 파일 앱을 확인해주세요.';}
async function downloadLastPhoto(){const photos=ride?ride.photos:encounterPhotos;const photo=latestPhoto?.photos===photos?latestPhoto:photos.length?{full:photos.at(-1),filename:photoFilename(selected,ride?.createdAt||Date.now(),photos.length)}:null;if(!photo)return;try{await downloadPhoto(photo.full,photo.filename,{share:true});toast(photoSavedMessage());}catch{toast('사진 다운로드를 시작하지 못했어요. 사진을 다시 눌러주세요.');}}
async function capture(){
 if(camState!=='live')return;
 const photos=ride?ride.photos:encounterPhotos;
 let photo;
 try{photo=capturePhoto($('cameraVideo'));}catch{toast('사진을 찍지 못했어요. 카메라가 준비되면 다시 눌러주세요.');return;}
 const capturedAt=Date.now(),filename=photoFilename(selected,capturedAt,photos.length+1);
 photos.push(photo.preview);latestPhoto={full:photo.full,filename,photos};
 // A denied download must not discard the captured journey photo.
 let requested=false;try{await downloadPhoto(photo.full,filename);requested=true;}catch{}
 if($('photoCount'))$('photoCount').textContent='사진 '+photos.length+'장';
 if($('photoStrip')){if($('photoStrip').className!=='memory-preview'){$('photoStrip').className='memory-preview';$('photoStrip').textContent='';}$('photoStrip').insertAdjacentHTML('beforeend',photoLink(photo.preview,selected,capturedAt,photos.length-1));}
 if($('cameraThumb')){$('cameraThumb').src=photo.preview;$('cameraThumb').hidden=false;}
 if($('downloadPhoto'))$('downloadPhoto').disabled=false;
 if($('cameraPhotoCount'))$('cameraPhotoCount').textContent='사진 '+photos.length+'장';
 const view=$('cameraView');if(view){view.classList.remove('capture-flash');void view.offsetWidth;view.classList.add('capture-flash');}
 if($('cameraStatus'))$('cameraStatus').textContent='사진 '+photos.length+'장 · 사진을 누르면 다시 저장할 수 있어요.';
 toast(requested?photoSavedMessage():'사진 다운로드를 시작하지 못했어요. 사진을 다시 눌러주세요.');
}
function reviewText(r){return rideDiary(r,getLanguage()).body;}
function post(r,actions=false){const d=rideDiary(r,getLanguage()),c=DIARY_COPY[getLanguage()],s=SOULS[r.soul];return '<article class="post" data-diary-id="'+esc(r.id)+'" style="--accent:'+s.color+';--tint:'+s.tint+'"><div class="post-head">'+characterArtwork(r.soul)+'<div><b>'+esc(d.title)+'</b><small>'+esc(d.date)+'</small></div></div>'+(r.photos.length?'<a class="diary-cover" href="'+esc(r.photos[0])+'" download="'+photoFilename(r.soul,r.createdAt,1)+'"><img src="'+esc(r.photos[0])+'" alt="'+({en:'A moment from our ride',ko:'우리 여정의 한순간',zh:'旅途中的一个瞬间'})[getLanguage()]+'"></a>':'<div class="diary-cover-empty">'+characterArtwork(r.soul)+'</div>')+'<div class="post-body">'+diaryGenerationMarkup(r)+'<p class="diary-body" lang="'+esc(d.language)+'" data-no-translate>'+esc(d.body)+'</p>'+(r.photos.length?'<div class="post-photos" data-shown="'+Math.min(8,r.photos.length)+'">'+r.photos.slice(0,8).map((src,i)=>photoLink(src,r.soul,r.createdAt,i)).join('')+'</div>'+(r.photos.length>8?'<button class="text-button" data-more-photos="'+esc(r.id)+'">'+({en:'More photos',ko:'사진 더 보기',zh:'更多照片'})[getLanguage()]+'</button>':''):'<div class="empty-photos">'+c.empty+'</div>')+(r.note?'<p class="post-note">'+esc(r.note)+'</p>':'')+(actions?'<div class="post-actions"><button data-diary-export="'+esc(r.id)+'">'+c.share+'</button><button data-diary-copy="'+esc(r.id)+'">'+c.copy+'</button><button data-export="'+esc(r.id)+'">'+c.image+'</button><button data-delete="'+esc(r.id)+'">'+c.remove+'</button></div>':'')+'</div></article>';}
const diaryJobs=new Map();
function diaryGenerationMarkup(r){const c=DIARY_GENERATION_COPY[getLanguage()];return r.diaryGeneration==='writing'&&diaryJobs.has(r.id)?'<p class="diary-generation" role="status" data-no-translate>'+c.writing+'</p>':['failed','writing'].includes(r.diaryGeneration)?'<div class="diary-generation" data-no-translate><p>'+c.failed+'</p><button class="text-button" data-diary-retry="'+esc(r.id)+'">'+c.retry+'</button></div>':'';}
function refreshDiaryCard(r){for(const el of document.querySelectorAll('[data-diary-id]'))if(el.dataset.diaryId===r.id)el.outerHTML=post(r,screen==='journal');}
async function writeDiary(record,language){
 if(diaryJobs.has(record.id))return;
 const controller=new AbortController();diaryJobs.set(record.id,controller);record.diaryGeneration='writing';refreshDiaryCard(record);
 const timer=setTimeout(()=>controller.abort('timeout'),65000);
 try{
  if(!await diarySaver.save(record)){record.diaryGeneration='failed';refreshDiaryCard(record);return;}
  const generated=await generateRideDiary(record,language,{signal:controller.signal});
  if(controller.signal.aborted)return;
  record.generatedDiary=generated;record.diaryGeneration='ready';
 }catch{if(controller.signal.aborted&&controller.signal.reason!=='timeout')return;record.diaryGeneration='failed';}
 finally{clearTimeout(timer);if(diaryJobs.get(record.id)===controller)diaryJobs.delete(record.id);}
 record.diary=rideDiary(record,language);await diarySaver.save(record);refreshDiaryCard(record);
}
let diaryNoteTimer;
const diarySaver=new DiaryAutosave({store:journeyStore,onState:(state,id)=>{if(draft?.id!==id||screen!=='finish')return;const status=$('saveStatus');if(status){status.dataset.saveState=state;status.textContent=DIARY_COPY[getLanguage()][state];}if(state==='saved')void loadRecordCount();}});
function persistDraft(){clearTimeout(diaryNoteTimer);if(!draft)return Promise.resolve(true);if($('rideNote'))draft.note=$('rideNote').value.slice(0,2000);draft.diary=rideDiary(draft,getLanguage());return diarySaver.save(draft);}
document.addEventListener('input',e=>{if(e.target.id!=='rideNote'||!draft)return;draft.note=e.target.value.slice(0,2000);$('saveStatus').textContent=DIARY_COPY[getLanguage()].saving;clearTimeout(diaryNoteTimer);diaryNoteTimer=setTimeout(()=>void persistDraft(),350);});
document.addEventListener('change',e=>{if(e.target.id==='rideNote')void persistDraft();});
function finish(){if(!ride)return;closeRideCamera();draft={...ride,seconds:Math.max(0,Math.floor((Date.now()-ride.started)/1000)),diaryVersion:2,diaryGeneration:'writing'};ride=null;const c=DIARY_COPY[getLanguage()];surface('finish','<section class="finish-layout diary-finish">'+post(draft)+'<div class="finish-copy" data-no-translate>'+riderReviews.markup('farewell')+bikeMemory.markup('farewell')+'<span class="eyebrow">A MEMORY TO KEEP</span><h1>'+c.intro+'</h1><p class="small">'+c.local+'</p><label for="rideNote">'+c.note+'</label><textarea id="rideNote" maxlength="2000" rows="4" placeholder="'+c.placeholder+'"></textarea><p class="small" id="saveStatus" role="status">'+c.saving+'</p><button class="primary accent" id="saveButton" data-action="save">'+c.view+'</button><button class="secondary" data-diary-export="'+esc(draft.id)+'">'+c.share+'</button><button class="secondary" data-diary-copy="'+esc(draft.id)+'">'+c.copy+'</button><button class="secondary" data-action="export-draft">'+c.image+'</button><button class="text-button" data-nav="home">'+c.back+'</button><div class="voice-status"></div></div></section>');updateURL('bike='+selected+'&view=memory');void writeDiary(draft,getLanguage());playLiveVoice(MEMORY_COPY[voiceLanguage].farewell,voiceLanguage);}
async function exportDiary(record,copy=false){const c=DIARY_COPY[getLanguage()],d=rideDiary(record,getLanguage());try{if(copy){await navigator.clipboard.writeText(d.text);toast(c.copied);}else if(isNative()){await shareNativeText(d);toast(c.exported);}else if(navigator.share){await navigator.share({title:d.title,text:d.text});}else{const blob=new Blob(['\uFEFF'+d.text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='velo-soul-diary-'+record.createdAt+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(c.downloaded);}}catch(error){if(error?.name!=='AbortError')toast(c.error);}}

const storage=(mode,action)=>journeyStore.run(mode,action);
async function migrateLegacy(){try{if(localStorage.getItem('velo-final-migrated'))return;const old=JSON.parse(localStorage.getItem('velo-soul-journeys-v2')||'[]');if(Array.isArray(old))for(const r of old){if(!r||!Object.hasOwn(SOULS,r.soul)||typeof r.id!=='string')continue;await storage('readwrite',s=>s.put({id:r.id,soul:r.soul,createdAt:Number(r.createdAt)||Date.now(),seconds:Number(r.seconds)||0,route:[],photos:[],placeEvents:[],events:[],note:typeof r.note==='string'?r.note.slice(0,160):''}));}localStorage.setItem('velo-final-migrated','1');}catch{}}
async function loadRecordCount(){try{await migrateLegacy();const count=await storage('readonly',s=>s.count());document.querySelectorAll('.record-count').forEach(e=>e.textContent=count);}catch{}}
async function save(){if(!draft)return;const button=$('saveButton');button.disabled=true;if(await persistDraft()){draft=null;await journal();}else if(button.isConnected)button.disabled=false;}
async function loadJournalPage(){
 if(screen!=='journal'||journeyPager.busy||!journeyPager.hasMore)return;
 const serial=journeyPager.generation;
 const button=$('journalMore');button.disabled=true;
 $('journalStatus').hidden=false;$('journalStatus').textContent='기억을 불러오는 중…';
 try{
  const page=await journeyPager.next();if(!page||screen!=='journal'||serial!==journeyPager.generation)return;
  document.querySelectorAll('.record-count').forEach(e=>e.textContent=page.total);
  if(journeyPager.records.length){$('journalGrid').insertAdjacentHTML('beforeend',page.records.map(r=>post(r,true)).join(''));}
  else{$('journalGrid').className='';$('journalGrid').innerHTML='<div class="empty"><span style="font-size:35px">✳</span><h2>첫 번째 이야기를 기다려요.</h2><p>소울과 함께 달리고, 우리의 순간을 남겨보세요.</p><button class="primary" data-nav="home">소울 만나러 가기 ↗</button></div>';}
  $('journalStatus').hidden=true;button.hidden=!page.hasMore;button.textContent='기록 더 보기';
 }catch{if(screen==='journal'&&serial===journeyPager.generation){$('journalStatus').textContent='기록을 불러오지 못했어요. 다시 시도해주세요.';button.hidden=false;button.textContent='다시 시도';}}
 finally{if(screen==='journal'&&serial===journeyPager.generation)button.disabled=false;}
}
async function journal(){document.title='우리의 기록 · VELO SOUL';surface('journal','<div class="journal"><span class="eyebrow">OUR LITTLE JOURNEYS</span><h1>우리가 함께한 순간.</h1><p class="small">소울의 시선으로 남긴 작은 라이딩 일기. 이 기기에서만 볼 수 있어요.</p><div id="journalList"><div class="journal-grid" id="journalGrid"></div><p class="small" id="journalStatus" style="margin:24px 0" role="status">기억을 불러오는 중…</p><button class="secondary" style="margin-top:24px" id="journalMore" data-action="journal-more" hidden>기록 더 보기</button></div></div>');updateURL('view=journeys');const serial=journeyPager.generation;await migrateLegacy();if(screen==='journal'&&serial===journeyPager.generation)await loadJournalPage();}
function showMorePhotos(button){const record=draft?.id===button.dataset.morePhotos?draft:journeyPager.records.find(r=>r.id===button.dataset.morePhotos);const grid=button.previousElementSibling;if(!record||!grid?.matches('.post-photos'))return;const start=Number(grid.dataset.shown)||0,end=Math.min(start+8,record.photos.length);grid.insertAdjacentHTML('beforeend',record.photos.slice(start,end).map((src,i)=>photoLink(src,record.soul,record.createdAt,start+i)).join(''));grid.dataset.shown=end;button.hidden=end>=record.photos.length;}
async function exportCard(r){
 toast('여정 카드를 만들고 있어요.');
 try{
  const s=SOULS[r.soul],d=rideDiary(r,getLanguage()),c=document.createElement('canvas');c.width=900;
  let x=c.getContext('2d');
  function lines(text,size){x.font=size+'px sans-serif';const out=[];for(const paragraph of text.split('\n')){let line='';for(const ch of paragraph){if(x.measureText(line+ch).width>780){out.push(line);line=ch;}else line+=ch;}out.push(line);}return out;}
  const titleLines=lines(d.title,38),bodyLines=lines(d.body,25),noteLines=r.note?lines(r.note,21):[],extra=r.photos.slice(1,5);
  const coverHeight=r.photos.length?450:240,coverTop=125+titleLines.length*48;
  c.height=coverTop+coverHeight+70+bodyLines.length*37+(extra.length?210:0)+(noteLines.length?40+noteLines.length*32:0)+120;
  x=c.getContext('2d');x.fillStyle='#fcfbf6';x.fillRect(0,0,c.width,c.height);x.fillStyle=s.color;x.font='600 20px sans-serif';x.fillText('VELO SOUL / A LITTLE MEMORY',55,55);
  x.fillStyle='#283b2d';x.font='600 38px sans-serif';titleLines.forEach((line,i)=>x.fillText(line,55,110+i*48));x.fillStyle='#748174';x.font='18px sans-serif';x.fillText(d.date,55,coverTop-20);
  x.fillStyle=s.tint;x.fillRect(55,coverTop,790,coverHeight);
  if(r.photos.length){const img=new Image();img.src=r.photos[0];await img.decode();const scale=Math.max(790/img.width,coverHeight/img.height),sw=790/scale,sh=coverHeight/scale;x.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,55,coverTop,790,coverHeight);}
  else{const portrait=await characterSnapshot(r.soul);if(portrait)x.drawImage(portrait,330,coverTop,240,240);}
  let y=coverTop+coverHeight+55;x.fillStyle='#344536';x.font='25px sans-serif';for(const line of bodyLines){x.fillText(line,55,y);y+=37;}
  if(extra.length){y+=15;for(const [i,src]of extra.entries()){const img=new Image();img.src=src;await img.decode();const crop=Math.min(img.width,img.height);x.drawImage(img,(img.width-crop)/2,(img.height-crop)/2,crop,crop,55+i*202,y,184,184);}y+=210;}
  if(noteLines.length){y+=25;x.font='21px sans-serif';for(const line of noteLines){x.fillText(line,55,y);y+=32;}}
  x.fillStyle=s.color;x.font='22px sans-serif';x.fillText('— '+s.en,55,c.height-48);
  if(isNative()){await saveNativeImage(c.toDataURL('image/png'),`velo-soul-${r.soul}-${r.createdAt}.png`,{share:true});toast('Saved on this device');return;}
  const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('image');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`velo-soul-${r.soul}-${r.createdAt}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('여정 카드 이미지를 저장했어요.');
 }catch{toast('이미지를 만들지 못했어요. 다시 시도해주세요.');}
}

async function navigate(target){if(ride&&!confirm(translate('아직 저장하지 않은 여정이 있어요. 기록하지 않고 나갈까요?')))return;if(draft&&!await persistDraft())return;ride=null;draft=null;target==='journal'?journal():target==='scan'?scanner():home();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.sceneMode){rideView.switch(b.closest('.camera-fullscreen'),b.dataset.sceneMode);return;}if(b.hasAttribute('data-scene-center')){rideView.center();return;}if(b.dataset.nav){e.preventDefault();navigate(b.dataset.nav);return;}if(b.dataset.meet){e.preventDefault();welcome(b.dataset.meet);return;}if(b.dataset.morePhotos){showMorePhotos(b);return;}if(b.dataset.diaryRetry){const r=draft?.id===b.dataset.diaryRetry?draft:journeyPager.records.find(x=>x.id===b.dataset.diaryRetry);if(r)void writeDiary(r,getLanguage());return;}if(b.dataset.diaryExport||b.dataset.diaryCopy){const id=b.dataset.diaryExport||b.dataset.diaryCopy;const r=draft?.id===id?draft:journeyPager.records.find(r=>r.id===id);if(r)void exportDiary(r,!!b.dataset.diaryCopy);return;}if(b.dataset.export){const r=journeyPager.records.find(r=>r.id===b.dataset.export);if(r)exportCard(r);return;}if(b.dataset.delete){if(confirm(translate('이 기기에 저장한 여정과 사진을 삭제할까요?'))){try{diaryJobs.get(b.dataset.delete)?.abort();await storage('readwrite',s=>s.delete(b.dataset.delete));await journal();toast('기록을 삭제했어요.');}catch{toast('기록을 삭제하지 못했어요.');}}return;}switch(b.dataset.action){case 'live-companion':startLiveCompanion();break;case 'camera-exit':companionPending=false;if(screen==='ride')closeRideCamera();else welcome(selected);break;case 'voice-start':startHandsFree();break;case 'voice-stop':handsFree?.stop();break;case 'audio-unlock':liveSpeech.prepare();voiceOn=true;if(currentLine?.dynamicLanguage)sayLive(currentLine.line,currentLine.dynamicLanguage);break;case 'vision-toggle':toggleVision();break;case 'vision-replay':if(currentLine?.dynamicLanguage){voiceOn=true;sayLive(currentLine.line,currentLine.dynamicLanguage);}break;case 'chat':soulChat.open(selected);break;case 'about':$('appSettingsDialog').close();$('infoDialog').showModal();break;case 'scan':navigate('scan');break;case 'encounter':encounter(false,true);break;case 'settings':$('appSettingsDialog').showModal();break;case 'settings-close':$('appSettingsDialog').close();break;case 'camera-start':if(['home','scan'].includes(screen))loadQRDecoder();if(camState==='live'){companionPending=false;visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=true;camera?.stop();camState='off';rideView.cameraStatus();clearTimeout(scanTimer);$('cameraView').classList.remove('live');$('cameraLabel').textContent=$('cameraView').classList.contains('awakened')?'CAMERA-FREE PREVIEW':'CAMERA OFF';$('cameraStatus').textContent='카메라를 껐어요.';b.textContent='카메라 켜기';if($('capturePhoto'))$('capturePhoto').disabled=true;}else await camera?.start();break;case 'wake':wake();break;case 'ride-start':startRide();break;case 'replay':handsFree?.stop();if(currentLine){voiceOn=true;if($('quietButton'))$('quietButton').textContent='♪ 목소리 쉬기';currentLine.dynamicLanguage?sayLive(currentLine.line,currentLine.dynamicLanguage):speak(currentLine.line,currentLine.key,currentLine.id||selected);}break;case 'quiet':handsFree?.stop();voiceOn=!voiceOn;b.textContent=voiceOn?'♪ 목소리 쉬기':'♪ 목소리 켜기';if(!voiceOn){stopVoice();voiceStatus('조용히 곁에 있을게.');}else if(currentLine)currentLine.dynamicLanguage?sayLive(currentLine.line,currentLine.dynamicLanguage):speak(currentLine.line,currentLine.key);break;case 'gps':gps();break;case 'ride-camera':rideCamera(true);break;case 'close-camera':closeRideCamera();break;case 'journal-more':loadJournalPage();break;case 'capture':capture();break;case 'download-photo':downloadLastPhoto();break;case 'finish':finish();break;case 'save':save();break;case 'export-draft':draft.note=$('rideNote').value.slice(0,2000);exportCard(draft);break;}});
$('infoDialog').querySelector('.dialog-close').onclick=()=>$('infoDialog').close();
document.addEventListener('keydown',e=>{const settings=document.querySelector('.camera-settings[open]');if(e.key==='Escape'&&settings){settings.open=false;settings.querySelector('summary').focus();e.preventDefault();return;}if(e.key==='Escape'&&$('rideCameraModal')&&!soulChat.isOpen()&&!document.querySelector('.audio-device-dialog[open]'))closeRideCamera();if(e.key==='Tab'&&$('rideCameraModal')&&!soulChat.isOpen()&&!document.querySelector('.audio-device-dialog[open]')){const items=[...$('rideCameraModal').querySelectorAll('button:not(:disabled),select:not(:disabled),summary')].filter(el=>el.getClientRects().length>0&&!el.closest('[hidden]'));if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function pauseCompanion(){handsFree?.stop();releaseWakeLock();companionPending=false;visionObserver?.stop();if($('visionToggle'))$('visionToggle').disabled=true;stopPlaceTalk();stopVoice();if(camera){camera.stop();camState='off';clearTimeout(scanTimer);$('cameraView')?.classList.remove('live');if($('cameraLabel'))$('cameraLabel').textContent='CAMERA PAUSED';if($('cameraStatus'))$('cameraStatus').textContent='화면을 떠나 카메라를 껐어요. 다시 켜려면 버튼을 눌러주세요.';if($('cameraStart')){$('cameraStart').disabled=false;$('cameraStart').textContent='카메라 다시 켜기';}if($('capturePhoto'))$('capturePhoto').disabled=true;}if(watch!==null){stopGPS();if(ride)ride.speed=null;gpsConnection='paused';gpsStatus='화면을 떠나 위치 기록을 멈췄어요. 다시 켜서 이어갈 수 있어요.';updateGPSUI();}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseCompanion();});
window.addEventListener('pagehide',()=>{for(const job of diaryJobs.values())job.abort();if(draft)void persistDraft();clearInterval(memoryIdleTimer);clearInterval(characterTimer);disposeCharacters();bikeMemory.controller?.abort();riderReviews.dispose();cleanup();audioSession.dispose();});window.addEventListener('popstate',async()=>{if(draft&&!await persistDraft())return;ride=null;draft=null;routeFromURL();});
function routeFromURL(){const p=new URLSearchParams(location.search),id=p.get('bike');if(p.get('view')==='journeys')journal();else if(p.get('view')==='scan')scanner();else if(Object.hasOwn(SOULS,id)){theme(id);p.get('view')==='camera'?encounter():welcome(id);}else home();}
startLanguageUI();$('voiceSelect').value=voiceLanguage;$('voiceSelect').addEventListener('change',e=>{const active=handsFree?.active;liveSpeech.prepare();setSpokenLanguage(e.target.value);soulChat.setInputLanguage(e.target.value);if(active){handsFree.start(selected,inputLanguage());requestWakeLock();}else if(!soulChat.isOpen()&&['welcome','camera'].includes(screen)){voiceOn=true;speak(SOULS[selected].hello,'hello');}});
$('languageSelect').addEventListener('change',()=>{bikeMemory.render();riderReviews.render();koreanMap.language();rideView.language();updateGPSUI();document.querySelectorAll('[data-weather-card]').forEach(e=>e.outerHTML=weatherMarkup(getLanguage()));paintWeatherUI();handsFree?.stop();visionObserver?.stop();const panel=$('visionPanel');if(panel)panel.outerHTML=visionMarkup();if($('visionToggle'))$('visionToggle').disabled=camState!=='live';if(screen==='journal')void journal();});
const microphoneInput=new MicrophoneInput({audioSession,onLevel:level=>{document.querySelectorAll('[data-mic-level]').forEach(m=>{m.value=level;m.setAttribute('aria-valuetext',Math.round(level*100)+'%');});}});
const CloudRecognition=createMicrophoneRecognition({input:microphoneInput,Socket:globalThis.WebSocket});
handsFree=new HandsFreeConversation({onTurn:turn=>rememberRideExchange(ride,turn),introduced:introducedSouls,getOpening:(id,lang)=>soulIntroduction(id,lang,voiceLanguage),onOpening:text=>{if($('cameraCaption'))$('cameraCaption').textContent=text;},Recognition:CloudRecognition,releaseInput:()=>microphoneInput.release(),getContext:chatSensorContext,speak:playLiveVoice,stopSpeech:stopVoice,onState:paintHandsFree,onTranscript:(text,final=true)=>{if($('cameraCaption'))$('cameraCaption').textContent='';for(const id of ['heardText']){const el=$(id);if(el){el.textContent=text;el.dataset.transcriptState=final?'confirmed':'interim';}}},onReply:text=>{if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent=text;$('quoteTitle').textContent='VOICE · Qwen';}}});
document.addEventListener('change',e=>{if(e.target.id==='liveInputLanguage'){const lang=e.target.value;setSpokenLanguage(lang);if(handsFree.active){handsFree.start(selected,lang);requestWakeLock();}}});
initNativeDevice({onPause:pauseCompanion,onBack:()=>{const dialog=document.querySelector('dialog[open]');if(dialog){dialog.close();return;}if($('rideCameraModal')){closeRideCamera();return;}if(screen!=='home'){navigate('home');return true;}return false;},onURL:url=>{const id=parseSoulQR(url,location.origin);if(id&&!ride&&!draft)welcome(id);}});
createAppNavigation({getLanguage});
routeFromURL();if(screen!=='journal')setTimeout(loadRecordCount,0);

function playLiveVoice(line,lang,id=selected,onState=()=>{}){stopVoice();activeVoiceSoul=id;currentLine={line,key:null,id,dynamicLanguage:lang};if($('cameraCaption'))$('cameraCaption').textContent=line;if(!voiceOn){onState('unavailable');return;}liveSpeech.speak(line,{language:lang,soul:id,source:introductionClip(line,id,lang),onState:state=>{paintSoulExpression(document,state==='playing'?'talking':state==='loading'?'thinking':'listening');document.body.classList.toggle('voice-playing',state==='playing'||state==='loading');voiceStatus(({loading:'목소리를 준비하고 있어요…',playing:lang==='ko'?'한국어 목소리 재생 중':'영어 목소리 재생 중',ended:'다시 듣기로 목소리를 들을 수 있어요.',blocked:'소리를 켜려면 듣기 버튼을 눌러주세요.',unavailable:'소리를 재생하지 못했어요. 다시 듣기를 눌러주세요.'})[state]);onState(state);}});}
async function triggerPlace(place){const source='gps';if(!ride||!place||screen!=='ride'||soulChat.isOpen())return;stopPlaceTalk();const epoch=placeEpoch,rideId=ride.id,lang=voiceLanguage;placeRequest=new AbortController();const controller=placeRequest;const timeout=setTimeout(()=>controller.abort(),30000);const status=$('placeStatus');status.textContent='GPS · '+place.name[getLanguage()];let line=placeFallback(place,selected,lang),generated=false;try{const response=await appFetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({soul:selected,language:lang,event:{placeId:place.id,source},messages:[{role:'user',content:'My device reports entering this catalog place area. Say one short in-character line.'}]})});if(response.ok){const data=await response.json();if(typeof data.reply==='string'&&data.reply.trim()&&data.soul===selected){line=data.reply;generated=true;}}}catch{}finally{clearTimeout(timeout);if(epoch===placeEpoch)placeRequest=null;}if(epoch!==placeEpoch||!ride||ride.id!==rideId||screen!=='ride')return;ride.placeEvents.push({placeId:place.id,source,generated,at:Date.now()});$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent='“'+line+'”';$('quoteTitle').textContent='GPS'+' · '+place.name[getLanguage()];status.textContent='GPS · '+(generated?'Qwen · ':translate('기본 안내 / AI 사용 불가')+' · ')+place.name[getLanguage()];sayLive(line,lang);}

function visionMarkup(){const c=VISION_COPY[getLanguage()];return `<section class="vision-panel" id="visionPanel" data-no-translate><p class="vision-notice">${c.notice}</p><button class="secondary" id="visionToggle" data-action="vision-toggle" aria-pressed="false" disabled>${c.start}</button><p id="visionStatus" class="small" role="status">${c.off}</p><p id="visionReply" class="vision-reply" aria-live="polite" hidden></p><button class="text-button" id="visionReplay" data-action="vision-replay" hidden>${c.listen}</button></section>`;}
function toggleVision(){if(visionObserver?.active){visionObserver.stop();if(!handsFree?.active)stopVoice();return;}if(camState!=='live'){toast(VISION_COPY[getLanguage()].camera);return;}stopPlaceTalk();if(!handsFree?.active)stopVoice();visionObserver?.stop();visionObserver=new SoulVisionObserver({capture:()=>captureVisionFrame($('cameraVideo')),getContext:()=>chatSensorContext(false).context,canObserve:()=>!weather.openingPending()&&!document.hidden&&camState==='live'&&!soulChat.isOpen()&&!placeRequest&&!handsFree?.isBusy()&&!document.body.classList.contains('voice-playing'),onState:state=>{const c=VISION_COPY[getLanguage()];if($('visionToggle')){$('visionToggle').textContent=visionObserver?.active?c.stop:c.start;$('visionToggle').setAttribute('aria-pressed',String(!!visionObserver?.active));}if($('visionStatus'))$('visionStatus').textContent=c[state]||c.failed;},onReply:(result,lang)=>{if($('visionReply')){$('visionReply').hidden=false;$('visionReply').textContent=result.reply;$('visionReplay').hidden=false;}if(ride){(ride.visionEvents??=[]).push({scene:result.scene,reply:result.reply,at:Date.now()});if($('rideQuote')){$('rideQuote').dataset.noTranslate='';$('rideQuote').textContent='“'+result.reply+'”';$('quoteTitle').textContent='CAMERA · Qwen';}}sayLive(result.reply,lang);}});visionObserver.start(selected,voiceLanguage);}

function chatSensorContext(withImage=true){const context={};const location=watch!==null?locationContext(gpsPoint,gpsSpeed):null;if(location)context.location=location;const weatherId=weather.reference();if(weatherId)context.weatherId=weatherId;const cameraConnected=camState==='live'&&!!visionObserver?.active;const result={context,cameraConnected};if(withImage&&cameraConnected){try{result.image=captureVisionFrame($('cameraVideo'));}catch{}}return result;}
function fullCameraMarkup(riding){return `<section class="camera-fullscreen" data-scene-mode="camera">${fullCameraInner(riding)}</section>`;}
function rideSettingsMarkup(){const c=RIDE_SURFACE_COPY[getLanguage()],h=HANDS_FREE_COPY[getLanguage()];return '<details class="camera-settings"><summary aria-label="'+c.more+'" title="'+c.more+'">···</summary><div class="ride-settings-panel"><h2 data-no-translate>'+c.more+'</h2><button id="cameraStart" data-action="camera-start">카메라 켜기</button><div class="camera-status" id="cameraStatus" role="status">카메라 권한을 기다리고 있어요.</div><button data-action="gps" data-gps-toggle data-no-translate>GPS</button><p class="camera-gps-status" data-gps-status data-no-translate role="status"></p><label data-no-translate>'+c.language+'<select id="liveInputLanguage">'+[['auto','Auto · 자동 · 自动'],['en','English'],['ko','한국어'],['zh','中文 → English']].map(([value,label])=>'<option value="'+value+'" '+(value===(handsFree?.language||inputLanguage())?'selected':'')+'>'+label+'</option>').join('')+'</select></label><div class="mic-level-row" data-no-translate><span>'+h.mic+'</span><meter data-mic-level min="0" max="1" value="0" aria-label="'+h.mic+'"></meter></div><button data-action="chat">소울과 대화하기 ↗</button><button id="wakeButton" data-action="wake">등장 애니메이션 다시 보기</button>'+weatherMarkup(getLanguage())+visionMarkup()+'<p class="small" data-no-translate>'+h.notice+'</p></div></details>';}
function fullCameraInner(riding){const c=RIDE_SURFACE_COPY[getLanguage()],photos=riding?ride.photos:encounterPhotos;return cameraMarkup(riding?'ride':'encounter')+rideViewMarkup(getLanguage())+'<div class="camera-top"><button class="camera-round" data-action="camera-exit" aria-label="'+c.close+'" data-no-translate>×</button><div class="camera-name"><b>'+SOULS[selected].en+'</b><span id="cameraGPS">GPS '+(watch!==null?'●':'○')+'</span></div>'+rideSettingsMarkup()+'</div>'+handsFreeMarkup()+'<div class="camera-live-caption" data-no-translate><p id="heardText" class="heard-text" aria-live="off"></p><p id="cameraCaption" role="status" aria-live="polite" aria-atomic="true"></p></div><span class="camera-focus" aria-hidden="true"><i></i></span><div class="camera-bottom"><div class="camera-shutter-row"><button class="camera-photo-preview" id="downloadPhoto" data-action="download-photo" aria-label="사진 다시 저장" '+(photos.length?'':'disabled')+'><img id="cameraThumb" alt="최근 촬영 사진" '+(photos.length?'src="'+esc(photos.at(-1))+'"':'hidden')+'><span id="cameraPhotoCount">'+photos.length+'</span><small>↓</small></button><button class="camera-shutter" id="capturePhoto" data-action="capture" aria-label="'+c.capture+'" data-no-translate disabled><span></span></button><button class="ride-finish" data-action="'+(riding?'finish':'live-companion')+'" data-no-translate>'+c[riding?'finish':'start']+'</button></div></div>';}
async function startLiveCompanion(){if(companionPending)return;if(!ride)startRide();voiceOn=true;liveSpeech.prepare();if(watch===null)gps();companionPending=true;if(!$('rideCameraModal'))rideCamera();else if(camState==='live'){companionPending=false;if(!visionObserver?.active)toggleVision();}else camera?.start();if(!handsFree?.active)toggleHandsFree();}

function sayLive(line,lang,id=selected,onState=()=>{}){if(handsFree?.active)return handsFree.announce(line,lang,onState);return playLiveVoice(line,lang,id,onState);}
async function requestWakeLock(){try{if(!document.hidden&&navigator.wakeLock&&!wakeLock){const lock=await navigator.wakeLock.request('screen');if(document.hidden||!handsFree?.active){await lock.release();return;}wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null;});}}catch{}}
function releaseWakeLock(){wakeLock?.release().catch(()=>{});wakeLock=null;}
function paintHandsFree(state){paintSoulExpression(document,['thinking','transcribing','synthesizing'].includes(state)?'thinking':state==='speaking'?'talking':['listening','hearing','quiet'].includes(state)?'listening':'rest');if(state==='listening')setTimeout(()=>flushCompanionMemories(),350);paintRideVoiceControls(document,getLanguage(),!!handsFree?.active,state);document.querySelectorAll('.camera-conversation').forEach(e=>e.dataset.voiceState=state);document.querySelectorAll('[data-action="audio-unlock"]').forEach(e=>e.hidden=!handsFree?.audioIssue);if(!handsFree?.active)releaseWakeLock();}
function inputLanguage(){try{const saved=localStorage.getItem('velo-soul-input-language');if(['en','ko','zh','auto'].includes(saved))return saved;}catch{}return voiceLanguage;}
function setSpokenLanguage(lang){voiceLanguage=lang==='ko'?'ko':'en';try{localStorage.setItem('velo-soul-input-language',lang);localStorage.setItem('velo-soul-voice-language',voiceLanguage);}catch{}$('voiceSelect').value=voiceLanguage;const select=$('liveInputLanguage');if(select)select.value=lang;preloadIntro();if(visionObserver?.active)visionObserver.start(selected,voiceLanguage);}
function startHandsFree(){if(handsFree?.active)return;stopPlaceTalk();stopVoice();voiceOn=true;preloadIntro();liveSpeech.prepare();const lang=$('liveInputLanguage')?.value||inputLanguage();handsFree.start(selected,lang);requestWakeLock();}
function toggleHandsFree(){if(handsFree?.active){handsFree.stop();return;}startHandsFree();}
function handsFreeMarkup(){const u=VOICE_LAYOUT[getLanguage()];return '<section class="camera-conversation" data-no-translate data-voice-state="'+(handsFree?.state||'off')+'">'+rideVoiceControlsMarkup(getLanguage(),!!handsFree?.active,handsFree?.state||'off')+'<button class="audio-retry" data-action="audio-unlock" hidden>'+u.sound+'</button></section>';}



